corpus = ["parse tree", "parse stack", "parse tree", "parse socket"]

def build_table(corpus):
    table = {}
    for text in corpus:
        parts = text.split()
        for i in range(len(parts) - 1):
            key = parts[i]
            nxt = parts[i + 1]
            if key not in table:
                table[key] = {}
            table[key][nxt] = table[key].get(nxt, 0) + 1
    return table

